def priority(task, state, m=5.0, a=0.6, b=0.2, cap=5.0, memcap=1.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    age = wait / est
    if age > cap:
        age = cap
    mem = task.resource_need / max(state.capacity, 1e-6)
    if mem > memcap:
        mem = memcap
    return tier / est * (1.0 + b * age) / (1.0 + a * mem)  # tuned (m=14.6,a=0.222,b=0.148,cap=18.9,memcap=0.43)

import math
def priority(task, state, b=0.5, m=2.0, g=0.5, c=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    base = task.weight / est * (1.0 + b * wait / est)
    if task.tenant == 'premium':
        wnorm = wait / max(mean, 1e-6)
        boost = 1.0 + (m - 1.0) * min(1.0, wnorm)
        slack = task.due - state.now - est
        if slack < c * mean:
            boost *= 1.0 + g * math.exp(-max(0.0, slack) / max(mean, 1e-6))
        return base * boost
    else:
        return base * (1.0 + g * min(1.0, wait / max(mean, 1e-6)))  # tuned (b=0.343,m=6.39,g=0.255,c=3.05)

def priority(task, state, t=1.0, u=1.0, p=5.0, s=1.0):
    est = max(task.estimated_runtime, 1e-6)
    bonus = t if task.tenant == 'premium' else 0.0
    tier = p if task.tenant == 'premium' else 1.0
    lateness = max(0.0, state.now + task.estimated_runtime - task.due)
    return (task.weight + bonus) / est + u * tier * lateness / max(est + s, 1e-6)  # tuned (t=0.303,u=1.75,p=1.64,s=0.86)

import math
def priority(task, state, b=2.0, m=2.0, c=1.0, guard=1e5, threshold=0.0):
    e = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / e * (1.0 + b * wait / e)
    lateness = state.now + e - task.due
    if lateness > threshold * e:
        return base + guard * (1.0 + max(0.0, lateness) / e)
    slack = max(0.0, task.due - state.now - e)
    return base * (1.0 + c * math.exp(-slack / max(state.mean_est, 1e-6)))
